const fs = require("fs");
const path = require("path");
const f = path.join(process.env.HOME, ".omp/agent/themes/slop.json");
const raw = fs.readFileSync(f, "utf8");
const json = JSON.parse(raw); // throws if malformed

const required = [
  ...["accent","border","borderAccent","borderMuted","success","error","warning","muted","dim","text","thinkingText"],
  ...["selectedBg","userMessageBg","customMessageBg","toolPendingBg","toolSuccessBg","toolErrorBg","statusLineBg"],
  ...["userMessageText","customMessageText","customMessageLabel","toolTitle","toolOutput"],
  ...["mdHeading","mdLink","mdLinkUrl","mdCode","mdCodeBlock","mdCodeBlockBorder","mdQuote","mdQuoteBorder","mdHr","mdListBullet"],
  ...["toolDiffAdded","toolDiffRemoved","toolDiffContext","syntaxComment","syntaxKeyword","syntaxFunction","syntaxVariable","syntaxString","syntaxNumber","syntaxType","syntaxOperator","syntaxPunctuation"],
  ...["thinkingOff","thinkingMinimal","thinkingLow","thinkingMedium","thinkingHigh","thinkingXhigh","bashMode","pythonMode"],
  ...["statusLineSep","statusLineModel","statusLinePath","statusLineGitClean","statusLineGitDirty","statusLineContext","statusLineSpend","statusLineStaged","statusLineDirty","statusLineUntracked","statusLineOutput","statusLineCost","statusLineSubagents"],
];

const missing = required.filter(k => !(k in json.colors));
console.log("JSON valid:", true);
console.log("name:", json.name);
console.log("total required:", required.length, "present:", required.length - missing.length);
console.log("missing:", missing);

// resolve var refs to confirm no dangling references (mirrors runtime resolution)
function resolve(v, seen = new Set()) {
  if (typeof v !== "string" || v === "" || v.startsWith("#")) return v;
  if (json.vars && v in json.vars) {
    if (seen.has(v)) throw new Error("circular: " + v);
    seen.add(v);
    return resolve(json.vars[v], seen);
  }
  return v; // literal string, fine (e.g. named color unlikely here)
}
let badRefs = [];
for (const [k, v] of Object.entries(json.colors)) {
  try { resolve(v); } catch (e) { badRefs.push([k, v, e.message]); }
}
console.log("dangling/circular var refs:", badRefs);

