    # tiling), floating after so they stack above
    order = sorted(
        range(len(windows)),
        key=lambda i: (
            windows[i]["workspace"].get("id", 0),
            windows[i]["floating"],
            windows[i]["at"][0],
            windows[i]["at"][1],
        ),
    )

